using System;
using System.Drawing;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace LumaDesk {
public class AccountForm:ChromeForm {
 bool registration;DarkField server,user,password,repeat;CheckBox import;Label message;SmoothButton submit,sync,logout,change;Timer refresh=new Timer{Interval=500};
 public AccountForm(){Text="Аккаунт и синхронизация";Build();refresh.Tick+=(s,e)=>{if(CloudSync.Connected&&sync!=null){message.Text=CloudSync.Status;sync.Enabled=logout.Enabled=change.Enabled=!CloudSync.Busy;sync.Invalidate();logout.Invalidate();change.Invalidate();}};refresh.Start();}
 void Clear(){while(Controls.Count>0)Controls[0].Dispose();Controls.Clear();sync=logout=change=null;}
 Label Label(string text,int x,int y,int w,int h=24){var label=new Label{Text=text,ForeColor=EditorArt.Muted,BackColor=EditorArt.Bg,Bounds=new Rectangle(x,y,w,h),Font=Theme.F(9)};Controls.Add(label);return label;}
 DarkField Field(int y,string text,bool secret=false){var field=new DarkField(new Rectangle(24,y,442,41),text,null);if(secret)((TextBox)field.Input).UseSystemPasswordChar=true;Controls.Add(field);return field;}
 void Build(){string serverDraft=server!=null&&!server.IsDisposed?server.Input.Text:CloudSync.Account.Server;string userDraft=user!=null&&!user.IsDisposed?user.Input.Text:CloudSync.Account.Username;Clear();if(CloudSync.Connected){SetContentSize(490,362);Label("АККАУНТ",24,23,442);var name=Label(CloudSync.Account.Username,24,58,442,36);name.ForeColor=EditorArt.Text;name.Font=Theme.F(20,FontStyle.Bold);Label(CloudSync.Account.Server,24,106,442,30);message=Label(CloudSync.Status,24,151,442,50);sync=new SmoothButton("Синхронизировать сейчас",new Rectangle(24,222,284,39),async(s,e)=>{await CloudSync.Synchronize();if(!IsDisposed)message.Text=CloudSync.Status;}){Primary=true};logout=new SmoothButton("Выйти",new Rectangle(320,222,146,39),async(s,e)=>{await CloudSync.Logout();if(!IsDisposed)Build();});change=new SmoothButton("Сменить пароль",new Rectangle(24,273,284,35),(s,e)=>{using(var f=new PasswordForm())f.ShowDialog(this);});Controls.Add(sync);Controls.Add(logout);Controls.Add(change);Label(Store.S.AutoSync?"Отправка после правок; проверка раз в 15 мин.":"Автосинхронизация выключена. Обновление вручную.",24,325,442,30);return;}
 SetContentSize(490,registration?620:544);Label("АККАУНТ И СИНХРОНИЗАЦИЯ",24,22,442);Label("Заметки, события и настройки на твоих компьютерах",24,48,442);Controls.Add(new SmoothButton("Войти",new Rectangle(24,79,214,35),(s,e)=>{registration=false;Build();}){Selected=!registration});Controls.Add(new SmoothButton("Регистрация",new Rectangle(252,79,214,35),(s,e)=>{registration=true;Build();}){Selected=registration});Label("АДРЕС СЕРВЕРА HTTPS",24,128,442);server=Field(149,serverDraft);server.Input.AccessibleName="Адрес сервера HTTPS";Label("ЛОГИН · ЛАТИНИЦА, ЦИФРЫ, ОТ 3 ДО 32 ЗНАКОВ",24,205,442);user=Field(226,userDraft);Label("ПАРОЛЬ · ОТ 12 ДО 128 ЗНАКОВ",24,282,442);password=Field(303,"",true);if(registration){Label("ПОВТОРИ ПАРОЛЬ",24,359,442);repeat=Field(380,"",true);}int y=registration?438:362;import=new CheckBox{Text="Добавить события и заметки с этого компьютера",Checked=registration,ForeColor=EditorArt.Text,BackColor=EditorArt.Bg,Bounds=new Rectangle(24,y,442,30)};Controls.Add(import);Label("Перед подключением текущие данные сохранятся в локальной копии.",24,y+39,442,32);message=Label("",24,y+77,442,36);submit=new SmoothButton(registration?"Создать аккаунт":"Войти и синхронизировать",new Rectangle(24,y+119,442,41),async(s,e)=>await Authenticate()){Primary=true};Controls.Add(submit);}
 async Task Authenticate(){if(CloudSync.Busy)return;try{CloudApi.ValidateServer(server.Input.Text);if(!Regex.IsMatch(user.Input.Text.Trim(),@"^[A-Za-z0-9_.-]{3,32}$"))throw new Exception("Логин: 3–32 латинских буквы, цифры, точка, дефис или подчёркивание.");if(password.Input.Text.Length<12||password.Input.Text.Length>128)throw new Exception("Пароль должен содержать 12–128 знаков.");if(registration&&password.Input.Text!=repeat.Input.Text)throw new Exception("Пароли не совпадают.");submit.Enabled=false;submit.Text=registration?"Создаём аккаунт…":"Подключаемся…";submit.Invalidate();bool ok=await CloudSync.Connect(server.Input.Text,user.Input.Text.Trim(),password.Input.Text,registration,import.Checked);if(IsDisposed)return;password.Input.Text="";if(repeat!=null&&!repeat.IsDisposed)repeat.Input.Text="";if(ok)Build();else{message.ForeColor=AppTheme.Error;message.Text=CloudSync.Status;submit.Enabled=true;submit.Text=registration?"Создать аккаунт":"Войти и синхронизировать";submit.Invalidate();}}catch(Exception e){if(IsDisposed)return;message.Text=e.Message;message.ForeColor=AppTheme.Error;if(submit!=null){submit.Enabled=true;submit.Text=registration?"Создать аккаунт":"Войти и синхронизировать";submit.Invalidate();}}}
 protected override void Dispose(bool disposing){if(disposing)refresh.Dispose();base.Dispose(disposing);}
}
public class PasswordForm:ChromeForm {
 DarkField oldPassword,newPassword,repeat;Label status;SmoothButton save;
 public PasswordForm(){Text="Сменить пароль";SetContentSize(460,402);AddLabel("ТЕКУЩИЙ ПАРОЛЬ",24);oldPassword=Field(48);AddLabel("НОВЫЙ ПАРОЛЬ · 12–128 ЗНАКОВ",106);newPassword=Field(130);AddLabel("ПОВТОРИ НОВЫЙ ПАРОЛЬ",188);repeat=Field(212);status=new Label{Bounds=new Rectangle(24,268,412,40),ForeColor=EditorArt.Muted,Text="После смены пароля другие компьютеры должны войти заново."};Controls.Add(status);save=new SmoothButton("Сменить пароль",new Rectangle(24,331,412,41),async(s,e)=>await Submit()){Primary=true};Controls.Add(save);}
 void AddLabel(string text,int y){Controls.Add(new Label{Text=text,Bounds=new Rectangle(24,y,412,22),ForeColor=EditorArt.Muted});}
 DarkField Field(int y){var f=new DarkField(new Rectangle(24,y,412,41),"",null);((TextBox)f.Input).UseSystemPasswordChar=true;Controls.Add(f);return f;}
 async Task Submit(){if(newPassword.Input.Text.Length<12||newPassword.Input.Text.Length>128||newPassword.Input.Text!=repeat.Input.Text){status.Text="Новый пароль: 12–128 знаков. Оба ввода должны совпадать.";return;}save.Enabled=false;bool ok=await CloudSync.ChangePassword(oldPassword.Input.Text,newPassword.Input.Text);if(IsDisposed)return;oldPassword.Input.Text=newPassword.Input.Text=repeat.Input.Text="";status.Text=CloudSync.Status;save.Enabled=true;if(ok)Close();}
}
}
